import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"参考：API 速查","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reference.md","filePath":"guide/reference.md"}`),a={name:`guide/reference.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="参考-api-速查" tabindex="-1">参考：API 速查 <a class="header-anchor" href="#参考-api-速查" aria-label="Permalink to “参考：API 速查”">​</a></h1><p>一页纸的速查表：类名 + 一句话 + 关键方法。要看实现的语义（每个注入点在哪、什么时候不干预）， 去 <a href="#去哪看真实实现">去哪看真实实现</a> 列出的文件。</p><h2 id="依赖坐标与模块" tabindex="-1">依赖坐标与模块 <a class="header-anchor" href="#依赖坐标与模块" aria-label="Permalink to “依赖坐标与模块”">​</a></h2><table tabindex="0"><thead><tr><th>模块 / 模组 id</th><th>坐标</th><th>内容</th></tr></thead><tbody><tr><td><code>fabric-api</code>（聚合器）</td><td><code>cn.enaium.fabricpvz:fabric-api:1.2.2</code></td><td>不含代码；模组依赖这个坐标就拿五个模块，聚合 jar 把五个模块<strong>装在自己里面</strong>（jar-in-jar），所以安装时只有一个文件</td></tr><tr><td><code>api-base</code></td><td>同上，随聚合器带出</td><td><code>PvzFabricApi</code>、<code>ModQuery</code>、事件总线（<code>api.event</code>）</td></tr><tr><td><code>api-events</code></td><td>同上</td><td><code>LawnEvents</code>（游戏事件）、<code>GameLifecycleEvents</code>（生命周期）与两个桥</td></tr><tr><td><code>api-plant</code></td><td>同上</td><td><code>PlantType</code>、<code>PlantRegistry</code>、<code>PlantOverrides</code>、<code>ProjectileOverrides</code>、<code>BoardOverrides</code>、<code>CustomPlantEvents</code>、<code>PlantRules</code>、<code>PlantHooks</code></td></tr><tr><td><code>api-resource</code></td><td>同上</td><td><code>ModImages</code>、<code>ModImageSlot</code>、<code>GameArt</code>、<code>ModReanims</code>、<code>ResourceOverrides</code>、<code>ResourceDiagnostics</code></td></tr><tr><td><code>api-zombie</code></td><td>同上</td><td><code>ZombieType</code>、<code>ZombieRegistry</code>、<code>ZombieOverrides</code>、<code>CustomZombieEvents</code>、<code>ZombieHooks</code></td></tr></tbody></table><p>API 是<strong>可选依赖</strong>：源码用到它时，模组自己在 Gradle 里声明 <code>cn.enaium.fabricpvz:fabric-api:1.2.2</code> （编译用 <code>compileOnly</code> / <code>testCompileOnly</code>，运行时用 <code>testImplementation</code> / <code>pvzRunClasspath</code> 且 <code>isTransitive = false</code>），并在 <code>fabric.mod.json</code> 的 <code>depends</code> 里写模块 id（或 <code>&quot;fabric-api&quot;</code>）。 不用 API 的模组不需要声明任何坐标。工具链不提供 API，也不替你选它的版本。</p><h2 id="api-base" tabindex="-1"><code>api-base</code> <a class="header-anchor" href="#api-base" aria-label="Permalink to “api-base”">​</a></h2><table tabindex="0"><thead><tr><th>类 / 方法</th><th>说明</th></tr></thead><tbody><tr><td><code>PvzFabricApi.MOD_ID</code> / <code>.BASE_MOD_ID</code> / <code>.VERSION</code></td><td><code>&quot;fabric-api&quot;</code> / <code>&quot;api-base&quot;</code> / API 版本</td></tr><tr><td><code>PvzFabricApi.isInitialized()</code> / <code>.getVersion()</code></td><td>API 自己的 <code>main</code> 入口点跑过没有 / 它的版本</td></tr><tr><td><code>PvzFabricApi.getMods()</code> / <code>.getModContainer(id)</code> / <code>.getEntrypoints(key, type)</code></td><td>Loader 查询的包装</td></tr><tr><td><code>ModQuery.isModLoaded(id)</code> / <code>.getModContainer(id)</code> / <code>.getModVersion(id)</code></td><td>轻量的 Loader 查询</td></tr><tr><td><code>Event&lt;T&gt;#register(listener)</code> / <code>#invoker()</code></td><td>事件注册与取当前 invoker（Fabric 同形）</td></tr><tr><td><code>EventFactory.createArrayBacked(接口, invoker 工厂)</code></td><td>创建数组驱动的事件；只有这一个工厂</td></tr><tr><td><code>ListenerException</code></td><td>监听器抛出的异常被包成它，带事件与监听器上下文</td></tr></tbody></table><h2 id="api-events" tabindex="-1"><code>api-events</code> <a class="header-anchor" href="#api-events" aria-label="Permalink to “api-events”">​</a></h2><table tabindex="0"><thead><tr><th>类 / 成员</th><th>说明</th></tr></thead><tbody><tr><td><code>LawnEvents.LEVEL_START</code></td><td><code>(Board, int level, int gameMode, int background)</code>：关卡初始化结束</td></tr><tr><td><code>LawnEvents.LEVEL_END</code></td><td><code>(Board, int result)</code>：关卡结束（胜/负）</td></tr><tr><td><code>LawnEvents.WAVE_START</code></td><td><code>(Board, int waveIndex, int[] zombieTypes)</code>：一波即将生成，返回 <code>true</code> 取消</td></tr><tr><td><code>LawnEvents.ZOMBIE_SPAWN</code></td><td><code>(Board, int zombieType, int row, boolean fromWave)</code>：返回 <code>true</code> 取消生成</td></tr><tr><td><code>LawnEvents.ZOMBIE_DEATH</code> / <code>.ZOMBIE_DAMAGE</code></td><td>死亡通知 / 伤害值链</td></tr><tr><td><code>LawnEvents.PLANT_PLACED</code> / <code>.PLANT_REMOVED</code> / <code>.PLANT_DAMAGE</code></td><td>种植通知 / 移除通知（带原因码）/ 伤害值链</td></tr><tr><td><code>LawnEvents.SUN_COLLECTED</code></td><td><code>(Board, int amount, int source)</code>：值链，返回实际入账的数量</td></tr><tr><td><code>LawnEvents.PLANTING_VALIDATED</code></td><td><code>(Board, int x, int y, int seedType, int reason)</code>：返回 <code>PLANTING_OK</code> 强制放行</td></tr><tr><td><code>LawnEvents.TICK</code></td><td><code>(Board, int tick)</code>：每 tick（每秒 100 次）</td></tr><tr><td><code>LawnEvents.PRE_DRAW</code> / <code>.POST_DRAW</code></td><td><code>(Board, Graphics)</code>：棋盘对象绘制之前 / 之后</td></tr><tr><td><code>GameLifecycleEvents.INITIALIZED</code></td><td>每个进程一次：框架启动完成（资源已加载，即将进主循环）</td></tr><tr><td><code>GameLifecycleEvents.EXITING</code></td><td>每个进程一次：开始关闭之前</td></tr><tr><td><code>LawnHooksBridge</code> / <code>AppHooksBridge</code></td><td>把游戏的钩子调用点接到事件总线上（由模块入口点安装）</td></tr></tbody></table><h2 id="api-plant" tabindex="-1"><code>api-plant</code> <a class="header-anchor" href="#api-plant" aria-label="Permalink to “api-plant”">​</a></h2><table tabindex="0"><thead><tr><th>类 / 方法</th><th>说明</th></tr></thead><tbody><tr><td><code>PlantType.builder(String id)</code> → <code>Builder</code> → <code>register()</code></td><td>注册一株新植物；<code>register()</code> 返回 <code>PlantType</code>，<code>seedType()</code> 是游戏用的整型 id</td></tr><tr><td><code>Builder</code> 全部字段</td><td>见<a href="./content.html">植物与僵尸</a>的表：<code>name</code> / <code>tooltip</code> / <code>almanacDescription</code> / <code>stringKeyStem</code> / <code>cost</code> / <code>refreshTime</code> / <code>reanimation</code> / <code>subClass</code> / <code>launchRate</code> / <code>health</code> / <code>projectile</code> / <code>burst</code> / <code>unlockAfter</code> / <code>packetArt…</code> / <code>aquatic</code> / <code>fungus</code> / <code>nocturnal</code> / <code>flying</code> / <code>upgrade</code> / <code>upgradeFrom</code> / <code>chooserVisible</code> / <code>onTick</code> / <code>onPlanted</code> / <code>plantRect</code> / <code>plantAttackRect</code> / <code>plantingRule</code></td></tr><tr><td><code>PlantType#id()</code> / <code>#seedType()</code> / <code>#definition()</code></td><td>注册 id / 游戏 id / 底层 <code>CustomPlantType</code></td></tr><tr><td><code>PlantRegistry.FIRST_SEED_TYPE</code></td><td>注册内容的 id 起点（<code>100</code>）</td></tr><tr><td><code>PlantRegistry.get(int)</code> / <code>.get(String)</code> / <code>.all()</code> / <code>.count()</code></td><td>查询已注册植物</td></tr><tr><td><code>PlantRegistry.isCustomSeedType(int)</code></td><td>id 是否落在留给注册内容的区间</td></tr><tr><td><code>PlantRegistry.canPlantAt(board, x, y, seedType)</code></td><td>游戏会不会允许这次种植（含模组规则）</td></tr><tr><td><code>PlantRegistry.place(board, x, y, seedType)</code></td><td>绕过种子包直接种一株</td></tr><tr><td><code>PlantRegistry.unregister(int)</code> / <code>.reset()</code></td><td>注销 / 清空（测试用）</td></tr><tr><td><code>PlantOverrides.of(seedType)</code> → <code>PlantOverride</code></td><td>覆盖已有植物（零售也算）的数值：<code>cost</code> / <code>refreshTime</code> / <code>launchRate</code> / <code>bodyHealth</code> / <code>spawnCountdown</code> / <code>biteInsteadOfEatZombieType</code> / <code>digestCountdown</code> / <code>spikeRockDamage</code> / <code>explosionBlast</code> / <code>producedCoins</code> / <code>crushProof</code></td></tr><tr><td><code>PlantOverrides.notOnGroundState(int)</code> / <code>.extraFireSeedType(int)</code></td><td>两条整局规则</td></tr><tr><td><code>PlantOverrides.registered()</code> / <code>.rules()</code> / <code>.reset()</code></td><td>诊断与清理</td></tr><tr><td><code>ProjectileOverrides.of(projectileType).damage(int)</code></td><td>覆盖抛射物伤害（一次表写入，无需 Mixin）</td></tr><tr><td><code>BoardOverrides.allowZombies(gameMode, zombieTypes…)</code></td><td>某模式额外允许的僵尸</td></tr><tr><td><code>BoardOverrides.allowZombieOnLevel(type, level, boolean)</code></td><td>覆盖允许表的一格</td></tr><tr><td><code>BoardOverrides.relaxZombieSpawnRules(boolean)</code></td><td>去掉起始关与权重的两个否决</td></tr><tr><td><code>BoardOverrides.beghouledWinningScore(int)</code> / <code>.killAllZombiesDamage(int)</code> / <code>.rainSeedInterval(int, int)</code> / <code>.stageHasGraveStones(boolean)</code></td><td>各模式的关卡数值</td></tr><tr><td><code>BoardOverrides.sunValues(int, int, int)</code> / <code>.sunMoneyCap(int)</code></td><td>阳光面值（普通/小/大）/ 存款上限</td></tr><tr><td><code>BoardOverrides.conveyorSeed(gameMode, from, to)</code> / <code>.sunSpawning(gameMode, coinType)</code> / <code>.skyDropCoin(coinType)</code></td><td>传送带与天降物</td></tr><tr><td><code>BoardOverrides.dropLootSunBranch(boolean)</code> / <code>.dropLootCoins(int, int, int)</code></td><td>敲僵尸掉阳光的分支与掉的三枚币</td></tr><tr><td><code>BoardOverrides.lastStandInitialSun(int)</code> / <code>.coinUsableSeedType(int)</code></td><td>Last Stand 开局阳光 / 金币的默认可用种子包</td></tr><tr><td><code>BoardOverrides.numWaves(retailWaves, waves)</code> / <code>.seedNotAllowedToPick(gameMode, seedTypes…)</code> / <code>.graveBusterNeedsGravesInverted(boolean)</code></td><td>波数表 / 选卡禁选 / 墓碑需求位取反</td></tr><tr><td><code>CustomPlantEvents.TICK</code> / <code>.PLACED</code></td><td>全局观察<strong>注册过的</strong>植物</td></tr><tr><td><code>PlantHooks</code></td><td>注入点本身（模块内部使用，公开以便诊断与测试）：<code>isUpgrade</code> / <code>isUpgradableTo</code> / <code>onPlanted</code> / <code>onTick</code> / <code>plantRect</code> / <code>drawPacketArt</code> / <code>fire</code> / <code>burstOf</code> …</td></tr><tr><td><code>PlantBehaviour</code> / <code>PlantingRule</code></td><td>行为的接口形态（builder 的回调被适配成它）</td></tr></tbody></table><h2 id="api-zombie" tabindex="-1"><code>api-zombie</code> <a class="header-anchor" href="#api-zombie" aria-label="Permalink to “api-zombie”">​</a></h2><table tabindex="0"><thead><tr><th>类 / 方法</th><th>说明</th></tr></thead><tbody><tr><td><code>ZombieType.builder(String id)</code> → <code>Builder</code> → <code>register()</code></td><td>注册一个新僵尸；<code>zombieType()</code> 是游戏用的 id</td></tr><tr><td><code>Builder</code> 全部字段</td><td>见<a href="./content.html">植物与僵尸</a>：<code>name</code> / <code>almanacDescription</code> / <code>stringKeyStem</code> / <code>bodyReanimation</code> / <code>headReanimation</code> / <code>headTrack</code> / <code>headBodyTrack</code> / <code>headHiddenTrack</code> / <code>headHiddenLayer</code> / <code>headTransform</code> / <code>health</code> / <code>helm</code> / <code>shield</code> / <code>flyingHealth</code> / <code>collider</code> / <code>attackRect</code> / <code>scale</code> / <code>canGoInPool</code> / <code>wave</code> / <code>pickWeight</code> / <code>startingLevel</code> / <code>points</code> / <code>onTick</code> / <code>onSpawned</code></td></tr><tr><td><code>ZombieRegistry.FIRST_ZOMBIE_TYPE</code></td><td>注册内容的 id 起点（<code>64</code>）</td></tr><tr><td><code>ZombieRegistry.get(int)</code> / <code>.get(String)</code> / <code>.all()</code> / <code>.count()</code> / <code>.isCustomZombieType(int)</code></td><td>查询</td></tr><tr><td><code>ZombieRegistry.spawn(board, zombieType, row, fromWave)</code></td><td>走游戏自己的生成路径生成一个</td></tr><tr><td><code>ZombieRegistry.WAVE_UI</code></td><td>&quot;不属于任何波次&quot;的生成常量</td></tr><tr><td><code>ZombieOverrides.of(zombieType)</code> → <code>ZombieOverride</code></td><td>覆盖已有僵尸的出生数值：<code>bodyHealth</code> / <code>helm</code> / <code>shieldHealth</code> / <code>phaseCounter</code> / <code>spawnsAs</code> / <code>bodyAnimation</code> / <code>mindControlBodyHealth</code></td></tr><tr><td><code>ZombieOverrides.mindControlBoost(int, int, float)</code> / <code>.burnImmunity(int, int…)</code> / <code>.coldRemovalChilledCounter(int)</code> / <code>.shieldAlwaysAbsorbs(boolean)</code></td><td>四条整局规则</td></tr><tr><td><code>ZombieOverrides.registered()</code> / <code>.rules()</code> / <code>.reset()</code> / <code>.remapType(int)</code> / <code>.apply(Zombie)</code></td><td>诊断与清理 / 类型替换查询</td></tr><tr><td><code>CustomZombieEvents.TICK</code> / <code>.SPAWNED</code></td><td>全局观察<strong>注册过的</strong>僵尸</td></tr><tr><td><code>ZombieHooks</code> / <code>ZombieBehaviour</code></td><td>注入点与行为接口（诊断、测试）</td></tr></tbody></table><h2 id="api-resource" tabindex="-1"><code>api-resource</code> <a class="header-anchor" href="#api-resource" aria-label="Permalink to “api-resource”">​</a></h2><table tabindex="0"><thead><tr><th>类 / 方法</th><th>说明</th></tr></thead><tbody><tr><td><code>ModImages.load(Class, String path)</code></td><td>从你的 jar 读一张 PNG</td></tr><tr><td><code>ModImages.blank(w, h)</code> / <code>.painted(w, h, painter)</code></td><td>空白/带笔刷的画布</td></tr><tr><td><code>ModImages.remapHue(image, pivotDegrees, compression)</code></td><td>逐像素改色相，保留饱和度/明度/alpha</td></tr><tr><td><code>ModImageSlot.claim(modId, name)</code></td><td>取一个游戏从不绘制的 <code>ImageID</code> 槽位</td></tr><tr><td><code>ModImageSlot#setImage(Image)</code> / <code>#image()</code> / <code>#bound()</code> / <code>#id()</code> / <code>#name()</code></td><td>装图 / 当前图 / 是否已绑好 / id / 名字</td></tr><tr><td><code>ModImageSlot.reset()</code></td><td>清空全部槽位（测试用）</td></tr><tr><td><code>GameArt.packetArt(seedType)</code></td><td>让游戏把该种子的选卡图画进一张 50×70 的图（没好返回 <code>null</code>）</td></tr><tr><td><code>GameArt.cachedPlantFrame(seedType)</code></td><td>游戏为光标预览/禅境花园构建的缓存帧</td></tr><tr><td><code>GameArt.installCachedPlantFrame(seedType, frame)</code></td><td>把<strong>你的</strong>帧放进游戏的缓存</td></tr><tr><td><code>ModReanims.overrideTrackArt(reanim, mapper)</code></td><td>换掉<strong>每一条带图</strong>轨道的图（幂等）</td></tr><tr><td><code>ModReanims.overrideTrackArt(reanim, trackNames, mapper)</code></td><td>只换指定名字的轨道</td></tr><tr><td><code>ModReanims.giveSeparateHeadLayer(plant)</code></td><td>补上&quot;头&quot;那一层 reanimation（幂等）</td></tr><tr><td><code>ResourceOverrides.addRoot(Path)</code> / <code>.addFile(pakPath, Path)</code> / <code>.addBytes(pakPath, byte[])</code></td><td>登记散包覆盖（目录 / 单文件 / 字节）</td></tr><tr><td><code>ResourceOverrides.overriddenNames()</code> / <code>.clear()</code> / <code>.installed()</code></td><td>诊断 / 清空 / Mixin 是否已装</td></tr><tr><td><code>ResourceDiagnostics</code></td><td>模块自己的记账（资源组回调、重装次数……），测试用</td></tr></tbody></table><h2 id="去哪看真实实现" tabindex="-1">去哪看真实实现 <a class="header-anchor" href="#去哪看真实实现" aria-label="Permalink to “去哪看真实实现”">​</a></h2><p>按&quot;想确认什么&quot;找文件（路径相对工作区根）：</p><table tabindex="0"><thead><tr><th>想确认</th><th>打开</th></tr></thead><tbody><tr><td>注册写进了哪张表、id 怎么分配</td><td><code>fabric-api/api-plant/src/main/java/cn/enaium/fabricpvz/api/plant/PlantRegistry.java</code>、<code>api-zombie/.../ZombieRegistry.java</code></td></tr><tr><td>每个注入点注入到游戏的哪个方法</td><td><code>fabric-api/api-plant/src/main/java/cn/enaium/fabricpvz/api/plant/PlantHooks.java</code>（javadoc 逐个写了游戏方法名与上游 <code>file:line</code>）、<code>api-zombie/.../ZombieHooks.java</code>、两个模块的 <code>mixin/</code> 目录</td></tr><tr><td>覆盖是在什么时候生效的</td><td><code>api-plant/.../mixin/PlantOverridesMixin.java</code>、<code>api-zombie/.../mixin/ZombieOverridesMixin.java</code>、<code>api-plant/.../mixin/BoardWavesMixin.java</code></td></tr><tr><td>事件由游戏的哪个调用点触发</td><td><code>PvZ-Portable/src/main/java/cn/enaium/fabricpvz/portable/lawn/hooks/LawnHooks.java</code> 与 <code>sexy/hooks/AppHooks.java</code>、<code>fabric-api/api-events/.../LawnHooksBridge.java</code></td></tr><tr><td>游戏本身怎么找资源、pak 的键规则</td><td><code>PvZ-Portable/src/main/java/cn/enaium/fabricpvz/portable/sexy/pak/PakInterface.java</code>、<code>.../pvzp/ResourceLocator.java</code></td></tr><tr><td>工具链到底给了什么</td><td><code>loom/README.md</code>、<code>loom/src/main/kotlin/cn/enaium/fabricpvz/loom/PvzModPlugin.kt</code>、<code>PvzDist.kt</code>、<code>JarInJar.kt</code></td></tr><tr><td>一个模组&quot;长什么样&quot;的模板</td><td><code>pvz-example-mod/</code>（最小：事件 + 三个 mixin）、<code>pvz-content-mod/</code>（内容 + 艺术 + 端到端测试）、<code>pvz-mod-95-edition/</code>（Kotlin + 规则覆盖）</td></tr></tbody></table>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};